    53	/** Validate each envelope against its actual storage key before listing it.
    54	 * Keep reads pure: invalid entries are ignored; cache sweeps handle deletion. */
    55	function readSummary(
    56	  key: string,
    57	  userId: string,
    58	  subjectKey: string,
    59	): LocalFillDraftSummary | undefined {
    60	  try {
    61	    const draft: unknown = JSON.parse(localStorage.getItem(key) ?? "null");
    62	    if (
    63	      !isRecord(draft) ||
    64	      draft.schemaVersion !== FILL_DRAFT_SCHEMA_VERSION ||
    65	      draft.userId !== userId ||
    66	      draft.subjectKey !== subjectKey ||
    67	      !isNonemptyString(draft.entryQuestionnaireId) ||
    68	      (draft.contextKey !== undefined && !isNonemptyString(draft.contextKey)) ||
    69	      typeof draft.savedAt !== "string" ||
    70	      isFillDraftExpired(draft.savedAt) ||
    71	      !Array.isArray(draft.forms) ||
    72	      !draft.forms.length
    73	    )
    74	      return undefined;
    75	
    76	    const scope: FillDraftScope = {
    77	      userId,
    78	      subjectKey,
    79	      entryQuestionnaireId: draft.entryQuestionnaireId,
    80	      ...(draft.contextKey === undefined
    81	        ? {}
    82	        : { contextKey: draft.contextKey as string }),
    83	    };
    84	    if (fillDraftStorageKey(scope) !== key) return undefined;
    85	
    86	    const ids = new Set<string>();
    87	    let primary: Record<string, unknown> | undefined;
    88	    for (const form of draft.forms) {
    89	      if (
    90	        !isRecord(form) ||
    91	        !isNonemptyString(form.questionnaireId) ||
    92	        typeof form.questionnaireVersion !== "string" ||
    93	        (form.title !== undefined && typeof form.title !== "string") ||
    94	        typeof form.structuredSkipped !== "boolean" ||
    95	        !isResponses(form.responses) ||
    96	        ids.has(form.questionnaireId)
    97	      )
    98	        return undefined;
    99	      ids.add(form.questionnaireId);
   100	      if (form.questionnaireId === scope.entryQuestionnaireId) primary = form;
   101	    }
   102	    if (!primary) return undefined;
   103	    return {
   104	      key,
   105	      scope,
   106	      title:
   107	        typeof primary.title === "string"
   108	          ? primary.title.trim() || undefined
   109	          : undefined,
   110	      savedAt: draft.savedAt,
   111	      formCount: draft.forms.length,
   112	    };
   113	  } catch {
