   118	/** Current user's drafts for exactly one subject, newest first. No registry,
   119	 * API requests, response revival or storage mutations are needed to list. */
   120	export function listLocalFillDrafts(
   121	  userId: string,
   122	  subjectKey: string,
   123	): LocalFillDraftSummary[] {
   124	  if (!userId || !subjectKey) return [];
   125	  const prefix = `${FILL_DRAFT_PREFIX}${userId}--${subjectKey}--`;
   126	  return fillDraftStorageKeys()
   127	    .filter((key) => key.startsWith(prefix))
   128	    .flatMap((key) => {
   129	      const summary = readSummary(key, userId, subjectKey);
   130	      return summary ? [summary] : [];
   131	    })
   132	    .sort(
   133	      (left, right) =>
   134	        Date.parse(right.savedAt) - Date.parse(left.savedAt) ||
   135	        left.key.localeCompare(right.key),
   136	    );
   137	}
   138	
   139	export function discardLocalFillDraft(scope: FillDraftScope): boolean {
   140	  return removeFillDraftCache(scope);
