     9	
    10	function equal(left: unknown, right: unknown): boolean {
    11	  return JSON.stringify(left) === JSON.stringify(right);
    12	}
    13	
    14	/** Apply only fields the clinician changed, retaining refreshed server fields. */
    15	function mergeFields(
    16	  baseline: unknown,
    17	  edited: unknown,
    18	  fresh: unknown,
    19	): unknown {
    20	  if (equal(baseline, edited)) return fresh;
    21	  if (!isRecord(baseline) || !isRecord(edited) || !isRecord(fresh)) {
    22	    return edited;
    23	  }
    24	  const merged = { ...fresh };
    25	  for (const key of new Set([
    26	    ...Object.keys(baseline),
    27	    ...Object.keys(edited),
    28	  ])) {
    29	    if (equal(baseline[key], edited[key])) continue;
    30	    if (!(key in edited)) delete merged[key];
    31	    else merged[key] = mergeFields(baseline[key], edited[key], fresh[key]);
    32	  }
    33	  return merged;
    34	}
    35	
    36	function rowId(row: unknown): string | undefined {
    37	  if (!isRecord(row)) return undefined;
    38	  return typeof row.id === "string" ? row.id : undefined;
    39	}
    40	
    41	function mergeRows(
    42	  baseline: unknown[],
    43	  edited: unknown[],
    44	  fresh: unknown[],
    45	  singleton: boolean,
    46	): unknown[] {
    47	  if (singleton && baseline.length <= 1 && edited.length <= 1) {
    48	    if (!edited.length) return baseline.length ? [] : fresh;
    49	    return [mergeFields(baseline[0], edited[0], fresh[0])];
    50	  }
    51	  const baselineIds = new Map(
    52	    baseline.flatMap((row) => {
    53	      const id = rowId(row);
    54	      return id ? [[id, row] as const] : [];
    55	    }),
    56	  );
    57	  const editedIds = new Map(
    58	    edited.flatMap((row) => {
    59	      const id = rowId(row);
    60	      return id ? [[id, row] as const] : [];
    61	    }),
    62	  );
    63	  const freshIds = new Set(fresh.map(rowId));
    64	  const merged = fresh.flatMap((row) => {
    65	    const id = rowId(row);
    66	    if (!id || !baselineIds.has(id)) return [editedIds.get(id ?? "") ?? row];
    67	    // Removing a baseline row is an intentional removal; a newly arrived
    68	    // server row is outside that baseline and remains visible.
    69	    if (!editedIds.has(id)) return [];
    70	    return [mergeFields(baselineIds.get(id), editedIds.get(id), row)];
    71	  });
    72	  for (const row of edited) {
    73	    const id = rowId(row);
    74	    if (id && freshIds.has(id)) continue;
    75	    // An untouched record removed on the server must not be resurrected.
    76	    if (id && baselineIds.has(id) && equal(row, baselineIds.get(id))) continue;
    77	    merged.push(row);
    78	  }
    79	  return merged;
    80	}
    81	
    82	/** Rebase saved/current user changes onto a new structured server prefill.
    83	 * Values with stable record ids merge by id. Encounter is a singleton
    84	 * request without an id, so its individual fields merge instead. */
    85	export function initializeStructuredResponse(
    86	  response: QuestionnaireResponse,
    87	  fresh: ResponseValue[],
    88	): QuestionnaireResponse {
    89	  const baseline = response.draft_context;
    90	  if (!baseline && !response.values.length) {
    91	    return { ...response, values: fresh, draft_context: fresh };
    92	  }
    93	  const values = fresh.map((entry) => {
    94	    const edited = response.values.find((value) => value.type === entry.type);
    95	    const before = baseline?.find((value) => value.type === entry.type);
    96	    if (!edited) {
    97	      return baseline && Array.isArray(entry.value)
    98	        ? ({ ...entry, value: [] } as ResponseValue)
    99	        : entry;
   100	    }
   101	    if (!Array.isArray(edited.value) || !Array.isArray(entry.value))
   102	      return edited;
   103	    return {
   104	      ...edited,
   105	      value: mergeRows(
   106	        Array.isArray(before?.value) ? before.value : [],
   107	        edited.value,
   108	        entry.value,
   109	        entry.type === "encounter",
   110	      ),
   111	    } as ResponseValue;
   112	  });
   113	  // An empty server result may omit the typed entry altogether.
   114	  for (const entry of response.values) {
   115	    if (!fresh.some((value) => value.type === entry.type)) values.push(entry);
   116	  }
   117	  return { ...response, values, draft_context: fresh };
   118	}
   119	
   120	export function structuredResponseHasEdits(
   121	  response: QuestionnaireResponse,
   122	): boolean {
   123	  return (
   124	    response.draft_context !== undefined &&
   125	    !equal(response.values, response.draft_context)
   126	  );
   127	}
   128	
   129	/** A prefill is not clinician input. Normalize it to the same empty value
   130	 * as the initial store so arriving server records cannot arm autosave. */
   131	export function draftIntentResponse(
   132	  response: QuestionnaireResponse,
   133	): QuestionnaireResponse {
   134	  const { draft_context, ...rest } = response;
   135	  if (draft_context && !structuredResponseHasEdits(response)) {
   136	    return { ...rest, values: [] };
   137	  }
   138	  return rest;
   139	}
