     1	import { useEffect, useMemo, useSyncExternalStore } from "react";
     2	
     3	import {
     4	  FILL_DRAFT_TTL_MS,
     5	  getFillDraftsVersion,
     6	  notifyFillDraftsChanged,
     7	  subscribeToFillDrafts,
     8	} from "./fillDraftCache";
     9	import { listLocalFillDrafts } from "./fillDraftList";
    10	
    11	const serverSnapshot = () => 0;
    12	
    13	export function useLocalFillDrafts(userId: string, subjectKey: string) {
    14	  const version = useSyncExternalStore(
    15	    subscribeToFillDrafts,
    16	    getFillDraftsVersion,
    17	    serverSnapshot,
    18	  );
    19	  const drafts = useMemo(
    20	    () => listLocalFillDrafts(userId, subjectKey),
    21	    [userId, subjectKey, version],
    22	  );
    23	
    24	  useEffect(() => {
    25	    if (!drafts.length) return;
    26	    const expiresAt = Math.min(
    27	      ...drafts.map((draft) => Date.parse(draft.savedAt) + FILL_DRAFT_TTL_MS),
    28	    );
    29	    const timeout = setTimeout(
    30	      notifyFillDraftsChanged,
    31	      Math.min(2 ** 31 - 1, Math.max(1, expiresAt - Date.now() + 1)),
    32	    );
    33	    return () => clearTimeout(timeout);
    34	  }, [drafts]);
    35	
    36	  return drafts;
    37	}

