 41	export interface DraftFormSnapshot {
 42	  questionnaireId: string;
 43	  /** `QuestionnaireRead.version` — a version bump invalidates this form
 44	   *  (the read spec exposes no modified_date yet). */
 45	  questionnaireVersion: string;
 46	  /** The questionnaire's title as it read when the draft was written —
 47	   *  the only human name available when a resume can no longer FETCH the
 48	   *  questionnaire. Optional because v2 drafts written before this field
 49	   *  existed are still valid; every reader must fall back. */
 50	  title?: string;
 51	  responses: Record<string, QuestionnaireResponse>;
 52	  structuredSkipped: boolean;
 53	}
 54	
 55	interface StoredFillDraft {
 56	  schemaVersion: number;
 57	  savedAt: string;
 58	  userId: string;
 59	  subjectKey: string;
 60	  entryQuestionnaireId: string;
 61	  contextKey?: string;
 62	  forms: DraftFormSnapshot[];
 63	}
 64	
 65	export interface LoadedFillDraft {
 66	  forms: DraftFormSnapshot[];
 67	  savedAt: string;
 68	  /** True when the saved session had structured answers the draft could
 69	   *  not carry (draftPolicy "exclude") — the restore bar says so. */
 70	  structuredSkipped: boolean;
 71	  /**
 72	   * Drop notice for the primary form, computed against the questionnaire's
 73	   * current questions before the clinician chooses Resume or Discard.
 74	   * Added forms are merged later when the host re-fetches them on resume.
 75	   */
 76	  dropped: DroppedDraftAnswer[];
 77	}
