 79	/** File payloads and plugin types that opt out cannot round-trip through
 80	 * JSON. Unknown plugin types are excluded until their definition is loaded. */
 81	function isDraftExcluded(response: QuestionnaireResponse): boolean {
 82	  if (!response.structured_type) return false;
 83	  const resolved = resolveStructuredType(response.structured_type);
 84	  return !resolved || resolved.draftPolicy === "exclude";
 85	}
 86	
 87	/** Keep serializable responses and all notes; annotate omitted file/plugin
 88	 * values so recovery can explain which sections need re-entry. */
 89	function partitionForDraft(responses: Record<string, QuestionnaireResponse>): {
 90	  safe: Record<string, QuestionnaireResponse>;
 91	  structuredSkipped: boolean;
 92	} {
 93	  const safe: Record<string, QuestionnaireResponse> = {};
 94	  let structuredSkipped = false;
 95	  for (const [id, response] of Object.entries(responses)) {
 96	    if (isDraftExcluded(response)) {
 97	      if (response.values.some(entryHasContent)) structuredSkipped = true;
 98	      // Files/plugin values may be unsafe to serialize, but their notes
 99	      // are ordinary clinician input and must survive reloads.
100	      safe[id] = { ...response, values: [], draft_context: undefined };
101	      continue;
102	    }
103	    safe[id] = response;
104	  }
105	  return { safe, structuredSkipped };
106	}
107	
108	/** Restore structured answers against live server baselines. Values that
109	 * cannot be drafted (files and excluded plugins) remain in the live store;
110	 * serializable edits rebase onto freshly fetched clinical records. */
111	export function preserveExcludedStructured(
112	  current: Record<string, QuestionnaireResponse>,
113	  next: Record<string, QuestionnaireResponse>,
114	): Record<string, QuestionnaireResponse> {
115	  const merged = { ...next };
116	  for (const [id, response] of Object.entries(current)) {
117	    if (!response.structured_type) continue;
118	    const fresh = merged[id];
119	    // Same guard the draft overlay uses: only where the question still
120	    // exists with the same structured_type.
121	    if (fresh && fresh.structured_type === response.structured_type) {
122	      if (isDraftExcluded(response)) {
123	        merged[id] = { ...response, note: fresh.note ?? response.note };
124	      } else if (response.draft_context !== undefined) {
125	        merged[id] = initializeStructuredResponse(
126	          fresh,
127	          response.draft_context,
128	        );
129	      }
130	    }
131	  }
132	  return merged;
133	}
134	
135	/**
136	 * Creation-time merge for resume paths: draft entries overlay the fresh
137	 * seed where the current question still accepts their shape and options.
138	 * Call sites that do not surface the drop list use this wrapper.
139	 */
140	export function mergeDraftIntoSeed(
141	  questions: Question[],
142	  draft: Record<string, QuestionnaireResponse>,
143	): Record<string, QuestionnaireResponse> {
144	  return mergeDraftResponses(questions, draft).responses;
145	}
146	
147	/** The live working state of one form, as the fill host reads it out of
148	 *  that form's store. */
149	export interface FillSessionFormState {
150	  questionnaire: QuestionnaireRead;
151	  responses: Record<string, QuestionnaireResponse>;
152	}
153	
154	function snapshotSession(forms: FillSessionFormState[]): {
155	  snapshots: DraftFormSnapshot[];
156	  anyContent: boolean;
157	} {
158	  const snapshots: DraftFormSnapshot[] = [];
159	  let anyContent = false;
160	  for (const form of forms) {
161	    const { safe, structuredSkipped } = partitionForDraft(form.responses);
162	    const hasContent = Object.values(safe).some(draftResponseHasContent);
163	    // Skipped values annotate an existing draft; only recoverable edits
164	    // create one. Server-prefilled rows are not clinician input.
165	    if (hasContent) anyContent = true;
166	    snapshots.push({
167	      questionnaireId: form.questionnaire.id,
168	      questionnaireVersion: String(form.questionnaire.version),
169	      title: form.questionnaire.title,
170	      responses: safe,
171	      structuredSkipped,
172	    });
173	  }
174	  return { snapshots, anyContent };
175	}
176	
177	/** Files cannot be restored, but choosing/replacing a file must still arm
178	 * the navigation prompt. Fingerprint file metadata without serializing blobs. */
179	function excludedEditIntent(
180	  responses: Record<string, QuestionnaireResponse>,
181	): unknown[] {
182	  return Object.values(responses).flatMap((response) => {
183	    if (response.structured_type !== "files") return [];
184	    return response.values.flatMap((entry) => {
185	      if (entry.type !== "files") return [];
186	      return (entry.value ?? []).map((file) => [
187	        response.question_id,
188	        file.name,
189	        file.file_data.name,
190	        file.file_data.size,
191	        file.file_data.lastModified,
192	      ]);
193	    });
194	  });
195	}
196	
197	/** Fingerprint clinician input, ignoring server-prefill values and their
198	 * baseline metadata. The same baseline also drives draft content detection. */
199	export function sessionEditSignature(forms: FillSessionFormState[]): string {
200	  return JSON.stringify(
201	    forms.map((form) => [
202	      form.questionnaire.id,
203	      Object.fromEntries(
204	        Object.entries(partitionForDraft(form.responses).safe).map(
205	          ([id, response]) => [id, draftIntentResponse(response)],
206	        ),
207	      ),
208	      excludedEditIntent(form.responses),
209	    ]),
210	  );
211	}
212	
213	/** Persist all forms in one session. Only recoverable user input earns a
214	 * draft; clearing that input removes a draft this session previously wrote.
215	 * Returns whether this write stored a draft successfully. */
216	export function saveFillDraft(
217	  scope: FillDraftScope,
218	  forms: FillSessionFormState[],
219	  /** Snapshots that belong to this draft but are NOT in the live session:
220	   *  a resume whose re-fetch of an added questionnaire failed. They ride
221	   *  through verbatim, because the alternative is that one transient
222	   *  network error during Resume silently and permanently deletes that
223	   *  form's drafted answers. */
224	  retained: DraftFormSnapshot[] = [],
225	  /** Whether an empty session may DELETE whatever is stored under this
226	   *  key. Only a session that has already stored a draft of its own may:
227	   *  emptiness means "the clinician removed their answers" solely for a
228	   *  session whose answers were ever in there. An edit the draft excludes
229	   *  (a file attachment) drives a save while leaving the
230	   *  safe partition empty, and that emptiness is nobody's deletion —
231	   *  clearing on it destroys an earlier session's recoverable answers and
232	   *  trades them for work that cannot be drafted at all. */
233	  mayClear = true,
234	): boolean {
235	  const { snapshots, anyContent } = snapshotSession(forms);
236	  const live = new Set(snapshots.map((snapshot) => snapshot.questionnaireId));
237	  const carried = retained.filter(
238	    (snapshot) => !live.has(snapshot.questionnaireId),
239	  );
240	  const carriedContent = carried.some((snapshot) =>
241	    Object.values(snapshot.responses).some(draftResponseHasContent),
242	  );
243	  if (!anyContent && !carriedContent) {
244	    if (mayClear) clearFillDraft(scope);
245	    return false;
246	  }
247	  const draft: StoredFillDraft = {
248	    schemaVersion: FILL_DRAFT_SCHEMA_VERSION,
249	    savedAt: new Date().toISOString(),
250	    userId: scope.userId,
251	    subjectKey: scope.subjectKey,
252	    entryQuestionnaireId: scope.entryQuestionnaireId,
253	    contextKey: scope.contextKey,
254	    forms: [...snapshots, ...carried],
255	  };
256	  try {
257	    return writeFillDraftCache(scope, JSON.stringify(draft));
258	  } catch {
259	    // Quota exceeded / storage disabled — autosave is best-effort, and a
260	    // write that never landed earns no authority to delete later.
261	    return false;
262	  }
263	}
264	
265	/**
266	 * Load the draft for this exact scope; mismatched, expired or corrupt entries
267	 * are removed. Primary-form version changes go through compatibility merge so
268	 * restorable answers survive and dropped answers are named for the restore bar.
269	 */
270	export function loadFillDraft(
271	  scope: FillDraftScope,
272	  questions: Question[],
273	): LoadedFillDraft | undefined {
274	  try {
275	    const raw = localStorage.getItem(fillDraftStorageKey(scope));
276	    if (!raw) return undefined;
277	    const draft = JSON.parse(raw) as StoredFillDraft;
278	    const primary = draft.forms?.find(
279	      (form) => form.questionnaireId === scope.entryQuestionnaireId,
280	    );
281	    if (
282	      draft.schemaVersion !== FILL_DRAFT_SCHEMA_VERSION ||
283	      draft.userId !== scope.userId ||
284	      draft.subjectKey !== scope.subjectKey ||
285	      draft.entryQuestionnaireId !== scope.entryQuestionnaireId ||
286	      draft.contextKey !== scope.contextKey ||
287	      isFillDraftExpired(draft.savedAt) ||
288	      !primary
289	    ) {
290	      removeFillDraftCache(scope);
291	      return undefined;
292	    }
293	    for (const form of draft.forms) {
294	      form.responses = reviveDraftResponses(form.responses);
295	    }
296	    const { dropped } = mergeDraftResponses(questions, primary.responses);
297	    return {
298	      forms: draft.forms,
299	      savedAt: draft.savedAt,
300	      structuredSkipped: draft.forms.some((form) => form.structuredSkipped),
301	      dropped,
302	    };
303	  } catch {
304	    removeFillDraftCache(scope);
305	    return undefined;
306	  }
307	}
308	
309	export function clearFillDraft(scope: FillDraftScope): void {
310	  removeFillDraftCache(scope);
311	}

