 27	const AUTOSAVE_DEBOUNCE_MS = 1500;
 28	
 29	/** The edit signature for ONE form — `sessionEditSignature` scoped to a
 30	 *  single-element input, so the per-form fingerprint is exactly what this
 31	 *  form contributes to the whole-session signature (one rule, never two). */
 32	function formSignature(form: FillFormEntry, store: FormStore): string {
 33	  return sessionEditSignature([
 34	    { questionnaire: form.questionnaire, responses: store.get(responsesAtom) },
 35	  ]);
