 38	interface UseFillSessionAutosaveArgs {
 39	  /** This session's draft key — undefined only before the questionnaire
 40	   *  loads. Supplied even in modes that never WRITE a local draft: a
 41	   *  successful submit must still clear a sibling draft stored under the
 42	   *  same key by an earlier plain session. */
 43	  scope: FillDraftScope | undefined;
 44	  /** false while resuming a SERVER draft: the server copy is authoritative
 45	   *  there, so nothing persists locally. Dirty tracking stays on either
 46	   *  way — the unsaved-changes prompt and the Draft chip are about the
 47	   *  clinician's un-submitted edits, not about where the bytes live. */
 48	  persistLocally?: boolean;
 49	  /** Every questionnaire in the session, primary first. */
 50	  forms: FillFormEntry[];
 51	  getStore: (key: string) => FormStore | undefined;
 52	  /** Bumped by the host whenever a StoreRegistrar (un)registers. */
 53	  storesVersion: number;
 54	  /** The draft this page instance detected, if any. */
 55	  restoredDraft: LoadedFillDraft | undefined;
 56	  /** Snapshots the host could not turn back into live forms (a resume
 57	   *  whose re-fetch failed). They stay in the persisted draft so a
 58	   *  transient error cannot destroy their answers. */
 59	  retainedSnapshots?: DraftFormSnapshot[];
 60	  /** Resume path for forms beyond the primary: the host re-adds them
 61	   *  (fetch by id, version-check, seed via initialResponses). */
 62	  onResumeAddedForms: (snapshots: DraftFormSnapshot[]) => void;
 63	}
