 65	/**
 66	 * Local autosave for a fill session. It subscribes to each registered form
 67	 * store behind one debounce, flushes on pagehide/unmount, and exposes the
 68	 * dirty and restore-prompt state rendered by the page chrome.
 69	 */
 70	export function useFillSessionAutosave({
 71	  scope,
 72	  persistLocally = true,
 73	  forms,
 74	  getStore,
 75	  storesVersion,
 76	  restoredDraft,
 77	  retainedSnapshots,
 78	  onResumeAddedForms,
 79	}: UseFillSessionAutosaveArgs) {
 80	  const [dirty, setDirty] = useState(false);
 81	  const [restoreDismissed, setRestoreDismissed] = useState(false);
 82	  // StoreRegistrar unregisters in a child effect cleanup. Keep the store
 83	  // available until this hook's cleanup has flushed the final keystroke.
 84	  const registeredStores = useRef(new Map<string, FormStore>());
 85	
 86	  // The subscription effect reads these without re-subscribing.
 87	  const scopeRef = useRef(scope);
 88	  scopeRef.current = scope;
 89	  const persistRef = useRef(persistLocally);
 90	  persistRef.current = persistLocally;
 91	  const retainedRef = useRef(retainedSnapshots);
 92	  retainedRef.current = retainedSnapshots;
 93	  // Set on successful submit: the draft served its purpose, so neither the
 94	  // pending debounce nor the unmount/pagehide flush may re-save it.
 95	  const finishedRef = useRef(false);
 96	  // Flipped by the first save that actually writes a draft. Until then this
 97	  // session has stored nothing, so an empty snapshot of it is not the
 98	  // clinician emptying their work and must not delete a draft an earlier
 99	  // session left under the same key — see `saveFillDraft`'s `mayClear`.
100	  const storedDraftRef = useRef(false);
101	  // Read by resumeRestoredDraft, which only ever fires from an event
102	  // handler well after mount.
103	  const restoredDraftRef = useRef(restoredDraft);
104	  restoredDraftRef.current = restoredDraft;
105	  // A detected draft the clinician has neither resumed nor discarded is
106	  // still theirs to decide about — see persistNow.
107	  const restorePendingRef = useRef(false);
108	  restorePendingRef.current = !!restoredDraft && !restoreDismissed;
109	
110	  const scopeKey = scope ? fillDraftScopeKey(scope) : undefined;
111	
112	  /** Include each form, using its creation seed until its store registers. */
113	  const snapshotAll = useCallback((): FillSessionFormState[] => {
114	    const snapshots: FillSessionFormState[] = [];
115	    for (const form of forms) {
116	      const store =
117	        getStore(form.key) ?? registeredStores.current.get(form.key);
118	      if (store) registeredStores.current.set(form.key, store);
119	      snapshots.push({
120	        questionnaire: form.questionnaire,
121	        responses:
122	          store?.get(responsesAtom) ??
123	          form.initialResponses ??
124	          initializeResponses(form.questionnaire.questions),
125	      });
126	    }
127	    return snapshots;
128	  }, [forms, getStore]);
129	
130	  /**
131	   * Write the whole session to its one draft entry. Never runs after a
132	   * successful submit, and never while `persistLocally` is off.
133	   *
134	   * While the restore prompt is still un-acted NOTHING persists: the
135	   * stored draft is the clinician's to accept or discard, and any write
136	   * from this session would overwrite it (a structured prefetch, a
137	   * keystroke).
138	   */
139	  const persistNow = useCallback(() => {
140	    const current = scopeRef.current;
141	    if (!current || !persistRef.current || finishedRef.current) return;
142	    if (restorePendingRef.current) return;
143	    const stored = saveFillDraft(
144	      current,
145	      snapshotAll(),
146	      retainedRef.current,
147	      storedDraftRef.current,
148	    );
149	    if (stored) storedDraftRef.current = true;
150	  }, [snapshotAll]);
151	
152	  /**
153	   * The session SHAPE changed (a form was added or removed) or a store
154	   * (un)registered — persist now. The debounce cannot cover this: on an
155	   * update React runs the previous effect's cleanup BEFORE the new
156	   * sections' StoreRegistrars register, so that flush would write a
157	   * snapshot missing the just-added forms and silently shrink the stored
158	   * draft (the Resume path re-adds drafted forms exactly this way).
159	   * Gated on `dirty`, because an untouched session has nothing of the
160	   * clinician's to write.
161	   */
162	  useEffect(() => {
163	    if (!scopeKey || !persistLocally || !dirty) return;
164	    persistNow();
165	  }, [
166	    scopeKey,
167	    persistLocally,
168	    dirty,
169	    storesVersion,
170	    retainedSnapshots,
171	    persistNow,
172	  ]);
173	
174	  // Not gated on `scopeKey`/`persistLocally`: dirty tracking is what arms
175	  // the unsaved-changes prompt and the Draft chip, and a session resuming
176	  // a SERVER draft needs both even though it writes no local draft.
177	  // `persistNow` is the thing that stands down, not the subscription.
178	  useEffect(() => {
179	    let timer: ReturnType<typeof setTimeout> | undefined;
180	
181	    const flush = () => {
182	      if (timer === undefined) return;
183	      clearTimeout(timer);
184	      timer = undefined;
185	      persistNow();
186	    };
187	
188	    // Per-form signature cache, keyed by form.key. A keystroke only ever
189	    // changes the ONE store that fired, so comparing just that form's own
190	    // cached entry is sufficient — no other form's signature could have
191	    // changed, so there is nothing to gain from joining them into a
192	    // session-wide value.
193	    //
194	    // Rebuilt from scratch on every (re)run of this effect — a form
195	    // add/remove or a store (un)registration bumps `storesVersion`, which
196	    // is a dependency below — by iterating the CURRENT `forms`/`getStore`.
197	    // A form no longer in that iteration simply never gets an entry, so a
198	    // removed form's stale signature can never survive to be compared
199	    // against again.
200	    //
201	    // Whatever is already in the stores when this is built is the
202	    // baseline, not an edit — this is where the structured widgets'
203	    // prefetched server rows sit.
204	    const formSignatures = new Map<string, string>();
205	    for (const form of forms) {
206	      const store = getStore(form.key);
207	      if (!store) continue;
208	      registeredStores.current.set(form.key, store);
209	      formSignatures.set(form.key, formSignature(form, store));
210	    }
211	
212	    // One shared debounce across every form of the session — the draft is
213	    // one localStorage entry, so one timer is all it can honour.
214	    const unsubscribers = forms.flatMap((form) => {
215	      const store = getStore(form.key);
216	      if (!store) return [];
217	      return [
218	        store.sub(responsesAtom, () => {
219	          if (finishedRef.current) return;
220	          // Compare this form's clinician input only. Prefill values are
221	          // normalized against draft_context; file metadata still marks
222	          // unsaved work even though the attachment cannot be drafted.
223	          const signature = formSignature(form, store);
224	          if (formSignatures.get(form.key) === signature) return;
225	          formSignatures.set(form.key, signature);
226	          setDirty(true);
227	          clearTimeout(timer);
228	          timer = setTimeout(() => {
229	            timer = undefined;
230	            persistNow();
231	          }, AUTOSAVE_DEBOUNCE_MS);
232	        }),
233	      ];
234	    });
235	
236	    // pagehide covers reload/close/bfcache; unmount covers in-app nav.
237	    window.addEventListener("pagehide", flush);
