239	      window.removeEventListener("pagehide", flush);
240	      flush();
241	      for (const unsubscribe of unsubscribers) unsubscribe();
242	    };
243	    // storesVersion re-runs the subscription when a form (un)registers.
244	  }, [storesVersion, forms, getStore, persistNow]);
245	
246	  /** Successful submit: drop the stored draft, stop all further saves,
247	   *  and clear the dirty flag SYNCHRONOUSLY (flushSync) — the success
248	   *  handler navigates right after this, and `useNavigationPrompt` must
249	   *  already see a pristine page or it blocks the redirect.
250	   *
251	   *  The clear runs off `scope`, not off whether this session PERSISTED
252	   *  locally: a server-draft session shares its key with the plain mount,
253	   *  and a local draft left behind there would prompt Resume with answers
254	   *  this submit already filed. */
255	  const finishDraft = useCallback(() => {
256	    finishedRef.current = true;
257	    const current = scopeRef.current;
258	    if (current) clearFillDraft(current);
259	    flushSync(() => {
260	      setDirty(false);
261	      setRestoreDismissed(true);
262	    });
263	  }, []);
264	
265	  const discardRestoredDraft = useCallback(() => {
266	    const current = scopeRef.current;
267	    if (current) clearFillDraft(current);
268	    // Discard drops the STORED draft — never what is on screen. The draft
269	    // only ever reaches the stores through Resume, so while the bar shows
270	    // they hold nothing but this session's own work: prefetched clinical
271	    // rows and whatever the clinician typed while ignoring the prompt.
272	    // Resetting them would destroy exactly the un-persisted work the
273	    // prompt gate protects.
274	    //
275	    // Persistence was standing down while the prompt was pending — flip
276	    // the gate synchronously (the ref recomputes only on the next render)
277	    // and write now, so anything typed in the meantime becomes a fresh
278	    // draft of its own instead of living un-persisted until the next
279	    // keystroke. An untouched session stores nothing, and the key it would
280	    // otherwise clear is already gone.
281	    restorePendingRef.current = false;
282	    setRestoreDismissed(true);
283	    persistNow();
284	  }, [persistNow]);
285	
286	  const dismissRestoreBar = useCallback(() => {
287	    restorePendingRef.current = false;
288	    setRestoreDismissed(true);
289	    persistNow();
290	  }, [persistNow]);
291	
292	  /** Apply the restored draft — the prompt bar's Resume affordance. The
293	   *  primary form's snapshot lands in the live store through the shared
