    24	/** JSON round-trips Dates to ISO strings; date/dateTime entries revive to
    25	 *  Date objects so the inputs' discriminant checks keep working. Shared by
    26	 *  the local-draft store and the server-draft (`?continue_draft=`) restore
    27	 *  path, whose dump went through the same JSON flattening. */
    28	export function reviveDraftResponses(
    29	  responses: Record<string, QuestionnaireResponse>,
    30	): Record<string, QuestionnaireResponse> {
    31	  for (const response of Object.values(responses)) {
    32	    // Server dumps are untyped blobs — a `values`-less entry is possible
    33	    // and must not throw the whole encounter overview.
    34	    for (const entry of response.values ?? []) {
    35	      // Fresh from JSON.parse the declared Date is actually a string —
    36	      // read through `unknown` at this one boundary.
    37	      const raw = (entry as { value?: unknown }).value;
    38	      if (
    39	        (entry.type === "date" || entry.type === "dateTime") &&
    40	        typeof raw === "string"
    41	      ) {
    42	        const revived = new Date(raw);
    43	        entry.value = isNaN(revived.getTime()) ? undefined : revived;
    44	      }
    45	    }
    46	  }
    47	  return responses;
    48	}

