 75	export function validateEncounterQuestion(
 76	  value: EncounterEdit | undefined,
 77	  questionId: string,
 78	): QuestionValidationError[] {
 79	  const errors: QuestionValidationError[] = [];
 80	
 81	  if (
 82	    value?.status === EncounterStatus.DISCHARGED &&
 83	    ["imp", "obsenc", "emer"].includes(value.encounter_class) &&
 84	    !value?.hospitalization?.discharge_disposition
 85	  ) {
 86	    errors.push(...validateFields(value, questionId, ENCOUNTER_FIELDS));
 87	  }
 88	
 89	  return errors;
 90	}
