    selectedFiles.forEach((file) => {
      const ext = file.name.split(".").pop()?.toLowerCase();
      if (ext && (FILE_EXTENSIONS.IMAGE as readonly string[]).includes(ext)) {
        const options = {
          initialQuality: 0.6,
          alwaysKeepResolution: true,
